func handler(w http.ResponseWriter, r *http.Request) {
	if !validPath.MatchString(r.URL.Path[1:]) {
		http.NotFound(w, r)
		return
	}

	cmd := exec.Command("/bin/sh", "-c", r.URL.Path)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(w, "Error: %v", err)
		return
