	data, err := ioutil.ReadAll(stdout)
	if err != nil {
		fmt.Fprintf(w, "Error: %v", err)
		return
	}

	err = cmd.Wait()
	if err != nil {
		fmt.Fprintf(w, "Error: %v", err)
		return
	}

	fmt.Fprintf(w, "%v", string(data))
}

func main() {
	http.HandleFunc("/", handler)
	http.ListenAndServe(":8080", nil)
